STORY = [('writer', '너 여기 앉아 봐. 신디한테 가서 뭐라고 한 거야?', 'Sit down right here. What on earth did you say when you went to see Cindy?', [(577, '너 여기 앉아봐'), (578, '너 신디한테 가서 뭐라고 한 거야')], ''), ('writer', '지금 신디네 회사 대표가 국장실에 와 있대요.', "They say Cindy's agency head is in the department director's office right now.", [(580, '지금 신디네 회사 대표가 국장실 와 있대요')], ''), ('seungchan', '아, 정말요?', 'Oh, really?', [(582, '아 정말요')], ''), ('ilyong', '이해가 안 되네. 내가 변 대표면 안 시킨다.', "I don't get it. If I were CEO Byun, I wouldn't put her on our show.", [(583, '이해가 안 되네'), (585, '내가 변 대표면 안 시킨다')], ''), ('writer', '말하는 거 하고는, 남의 일이에요?', "Listen to the way you talk, is this someone else's program?", [(586, '말하는 거 하고는'), (586, '남의 일이에요')], ''), ('writer', '너 신디 어떻게 섭외한 거야?', 'How did you manage to cast Cindy?', [(589, '너 신디 어떻게 섭외한 거야')], ''), ('seungchan', '저는 그냥 같이 하시면 좋겠다, 이렇게 얘기한 것뿐인데요.', 'I simply told her it would be nice if she joined us, that is all.', [(591, '저는 그냥'), (591, '하시면 좋겠다'), (592, '이렇게 얘기한 것 뿐인데')], ''), ('writer', '얼굴이네! 얼굴에 꽂힌 거지?', "It was your face! She fell for your face, didn't she?", [(593, '얼굴이네'), (594, '얼굴에 꽂힌 거지')], ''), ('ilyong', '그렇다니까! 내가 가서 말했을 땐 역효과 났잖아.', 'That has to be it! When I went and asked her, it completely backfired.', [(596, '그렇다니까'), (598, '역효과 났지')], ''), ('writer', '일반인 훈남한테 빠진 톱스타 같은 거네요?', "So it's like a top star falling for an ordinary handsome guy?", [(600, '빠진 톱스타')], ''), ('seungchan', '아니, 무슨 말씀을요.', 'No, what are you talking about.', [(601, '아니, 아니')], ''), ('ilyong', '맞아, 신디가 완전 얼굴 팬이었어.', "That's right, Cindy turned out to be a total fan of good looks.", [(595, '얼빠였어')], '')]
