WALK = [(0, None, "'Sit down right here. What on earth did you say when you went to see Cindy?'"), (1, None, "'They say Cindy's agency head is in the department director's office right now.'"), (2, None, "'Oh, really?'"), (3, None, "'I don't get it. If I were CEO Byun, I wouldn't put her on our show.'"), (4, None, "'Listen to the way you talk, is this someone else's program?'"), (5, None, "'How did you manage to cast Cindy?'"), (6, None, "'I simply told her it would be nice if she joined us, that is all.'"), (7, None, "'It was your face! She fell for your face, didn't she?'"), (8, None, "'That has to be it! When I went and asked her, it completely backfired.'"), (9, None, "'So it's like a top star falling for an ordinary handsome guy?'"), (10, None, "'No, what are you talking about.'"), (11, None, "'That's right, Cindy turned out to be a total fan of good looks.'")]
